#include <bits/stdc++.h>using namespace std;using ll = long long;void solve() {     string s;     cin >> s;     ll z=count(s.begin(),s.end(),'0');     ll o=count(s.begin(),s.end(),'1');       for(ll i=0;i<s.length();i++)     {         if(s[i]=='1')z--;         if(s[i]=='0')o--;           if(z<0 || o<0)         {            cout << s.size()-i<<endl;             return;                    }     }     cout << 0<< endl; } int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) {       solve();    }    return 0;}